---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Prompt starters: Suggested tasks that fill the composer in one click.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change prompt-starters.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './prompt-starters.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" draws it in the Soft style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft") */
  'data-style'?: 'soft';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', 'bare', className]} data-c="prompt-starters" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="psx">
  <div class="psx-grid"></div>
  <div class="psx-in"><span class="psx-ph">Pick a starter or type your own</span><span class="psx-tx"></span><button class="psx-go" aria-label="Send" data-tip="Send" disabled><svg class="i s"><use href="#i-up"/></svg></button></div>
  <button class="pill ghost sm psx-sh"><svg class="i xs"><use href="#i-refresh"/></svg>Shuffle</button>
</div>
  </Fragment></div>
</div>
<script>
  import './prompt-starters.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Prompt starters ---------- */
.psx{display:flex;flex-direction:column;gap:10px;align-items:center}
.psx-grid{display:grid;grid-template-columns:1fr 1fr;gap:var(--dm-s-2);width:100%}
/* white cards with a dimmed grey edge; the picked one's edge is a step stronger */
.psx-c{display:flex;flex-direction:column;gap:6px;align-items:flex-start;text-align:left;padding:var(--dm-s-3);border-radius:calc(14px * var(--dm-rk));background:var(--dm-chip);transition:background .25s,box-shadow .25s}
@media (hover:hover) and (pointer:fine){.psx-c:hover{background:var(--dm-hover)}}
.psx-c.on{background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-rail) 50%,transparent),0 1px 2px rgba(0,0,0,.04)}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]) .psx-c.on{background:var(--dm-hover)}}
:root[data-theme="dark"] .psx-c.on{background:var(--dm-hover)}
.psx-ic{width:28px;height:28px;border-radius:calc(9px * var(--dm-rk));display:grid;place-items:center;background:var(--dm-surface)!important}
.psx-c b{font-weight:500;font-size:13.5px}
.psx-c span.d{font-size:12px;color:var(--dm-muted);line-height:1.4}
.psx-in{display:flex;align-items:center;gap:var(--dm-s-2);width:100%;min-height:46px;padding:6px 6px 6px var(--dm-s-4);border-radius:var(--dm-r-pill);background:var(--dm-surface);box-shadow:var(--dm-shadow);font-size:13.5px;position:relative}
.psx-ph{color:var(--dm-muted);transition:opacity .3s}
.psx-in.has .psx-ph{display:none}
.psx-tx{flex:1;min-width:0}
.psx-tx .w{animation:lvw .4s var(--dm-ease) both}
@keyframes lvw{from{opacity:0;filter:blur(3px)}to{opacity:1;filter:none}}
.psx-go{margin-left:auto;width:32px;height:32px;border-radius:50%;display:grid;place-items:center;background:var(--dm-accent);color:var(--dm-on-accent);flex:none;transition:opacity .3s}
.psx-go[disabled]{opacity:1;cursor:not-allowed;background:var(--dm-dis-hatch),var(--dm-dis-fill);color:var(--dm-dis);box-shadow:var(--dm-soft-ring)}
.psx-sh svg{transition:transform .6s var(--dm-ease)}
@media (hover:hover) and (pointer:fine){.psx-sh:hover svg{transform:rotate(180deg)}}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, $$, DM, I, ctl, stagger } from '../core/core.js';
DM.def('prompt-starters', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{up}', I('up')).replace('{shuffle}', I('refresh','xs'));
  const sets = [
    [['grid','var(--dm-pb)','var(--dm-pb-bg)','Audit a page','Check the pricing page for spacing and contrast','Audit pricing for spacing and contrast'],['edit','var(--dm-pl)','var(--dm-pl-bg)','Rewrite copy','Make the onboarding intro shorter','Make the onboarding intro shorter'],['code','var(--dm-pm)','var(--dm-pm-bg)','Export tokens','Turn colour and spacing into CSS variables','Export the tokens as CSS variables'],['layers','var(--dm-pp)','var(--dm-pp-bg)','Compare frames','Diff the mobile and desktop frames','Diff the mobile and desktop frames']],
    [['chart','var(--dm-pt)','var(--dm-pt-bg)','Explain a metric','Why did activation drop last week','Why did activation drop last week?'],['mail','var(--dm-pk)','var(--dm-pk-bg)','Draft an email','Announce the new pricing to customers','Announce the new pricing by email'],['bug','var(--dm-pr)','var(--dm-pr-bg)','Find a bug','Trace why checkout logs people out','Fix checkout logging people out'],['figma','var(--dm-pl)','var(--dm-pl-bg)','Build from Figma','Turn the hero frame into code','Build the hero frame in React']]
  ];
  let si = 0;
  const grid = $('.psx-grid', r), tx = $('.psx-tx', r), inp = $('.psx-in', r), go = $('.psx-go', r);
  function paint(){
    grid.innerHTML = sets[si].map((s, i) => `<button class="psx-c" data-i="${i}"><span class="psx-ic" style="color:${s[1]};background:${s[2]}">${I(s[0] === 'bug' ? 'alert' : s[0])}</span><b>${s[3]}</b><span class="d">${s[4]}</span></button>`).join('');
    stagger($$('.psx-c', grid), 60);
    $$('.psx-c', grid).forEach(b => b.onclick = () => pick(b));
  }
  let k = null;
  function pick(b){
    $$('.psx-c', grid).forEach(x => x.classList.toggle('on', x === b));
    if (k) k.stop(); k = ctl(c); const kk = k; c.offs.push(() => kk.stop());
    tx.innerHTML = ''; inp.classList.add('has'); go.disabled = false;
    kk.run(async () => { for (const w of sets[si][b.dataset.i][5].split(' ')){ tx.insertAdjacentHTML('beforeend', `<span class="w">${w} </span>`); await kk.wait(40); } });
  }
  $('.psx-sh', r).onclick = () => { si = (si + 1) % sets.length; tx.innerHTML = ''; inp.classList.remove('has'); go.disabled = true; paint(); };
  go.onclick = () => { tx.innerHTML = '<span class="w">Sent to the agent</span>'; go.disabled = true; $$('.psx-c', grid).forEach(x => x.classList.remove('on')); };
  // the box starts empty: a starter fills it when someone picks one, in one short line
  paint();
});
